with matched_keys as (select id from orders intersect all select id from orders where store_id is not null), verified as (select s.* from orders s join matched_keys k on s.id = k.id) select case when shipping_fee >= 41 then 'HIGH' else 'LOW' end as shipping_fee_tier, store_id, customer_id, count(distinct id) as distinct_ids, percentile_approx(amount, 0.9) as amount_p90, corr(shipping_fee, amount) as corr_shipping_fee_amount, count_if(channel = 'mobile') as mobile_events from verified group by case when shipping_fee >= 41 then 'HIGH' else 'LOW' end, store_id, customer_id having amount_p90 > 0 order by corr_shipping_fee_amount nulls last
